/**
 * dsh-client-ui-password-generator — browser half (client).
 *
 * Registers a "密码生成器" entry into the `sidebar.footer.action` list slot
 * (beside Settings) and renders a small modal with four complexity tiers:
 *   低 / 中 / 高  — generated locally with `crypto.getRandomValues`;
 *   🎲 (有意义)   — generated by the host half through `ctx.llm`, streamed
 *                   over the existing Remote channel; API key never leaves
 *                   the host process (plan §4.5, path ①).
 *
 * No history: no localStorage / IndexedDB / settings / session writes. The
 * password lives only in React state inside the modal and is destroyed the
 * moment the modal closes (the component unmounts).
 *
 * Build contract: this file is the BODY of the lazy-CJS factory emitted by
 * `scripts/build.mjs`. Two locals are provided by the wrapper:
 *   _react      — require("react")
 *   _primitives — require("@deepseek-ai/dsh-client-ui-primitives")
 * No JSX / TypeScript — plain React.createElement.
 */

const React = _react;
const { Button, Modal, Toast, writeClipboard } = _primitives;

