/* ── Remote contribution for the host `passwordGenerator` service ──
 * Mirrors the host gateway's SRC-derived descriptor (src-json would be
 * rejected by the client mount, which demands strict codecs), so a tiny
 * pass-through schema stands in for the generated zod codec.
 */
const passThroughSchema = {
  parse(value) {
    return value;
  },
};

const TYPERT_REMOTE = {
  package: "dsh-client-ui-password-generator",
  descriptors: [
    {
      id: "dsh-client-ui-password-generator#passwordGenerator/generateMeaningful",
      service: "passwordGenerator",
      namespace: "passwordGenerator",
      method: "generateMeaningful",
      invocation: { kind: "direct" },
      parameters: [
        {
          name: "request",
          wire: "request",
          source: "json",
          codec: {
            mode: "strict",
            typeSymbol: "dsh-client-ui-password-generator#generateMeaningful:request",
            schema: passThroughSchema,
          },
        },
      ],
      result: {
        mode: "strict",
        typeSymbol: "dsh-client-ui-password-generator#generateMeaningful:result",
        schema: passThroughSchema,
      },
      sourceLocation: { file: "src/client/index.js", line: 1, column: 1 },
    },
  ],
};

/* ── complexity tiers & character sets (0O1lI removed) ── */
const CONFIGS = {
  low: { length: 8, sets: ["lower", "digit"] },
  mid: { length: 12, sets: ["lower", "upper", "digit"] },
  high: { length: 16, sets: ["lower", "upper", "digit", "symbol"] },
};

const SETS = {
  lower: "abcdefghjkmnpqrstuvwxyz",
  upper: "ABCDEFGHJKMNPQRSTUVWXYZ",
  digit: "23456789",
  symbol: "!@#$%^&*()-_=+[]{};:,.<>?",
};

/* ── cryptographically secure randomness (rejection sampling, no bias) ── */
function secureRandomInt(maxExclusive) {
  if (maxExclusive <= 0) throw new Error("bad range");
  const range = Math.floor(0x100000000 / maxExclusive) * maxExclusive;
  const buf = new Uint32Array(1);
  let x;
  do {
    crypto.getRandomValues(buf);
    x = buf[0];
  } while (x >= range);
  return x % maxExclusive;
}

const pickChar = (set) => set[secureRandomInt(set.length)];

function shuffle(arr) {
  for (let i = arr.length - 1; i > 0; i--) {
    const j = secureRandomInt(i + 1);
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

/** Generate one random password for the low/mid/high tiers (guaranteed class coverage). */
function generate(level) {
  const cfg = CONFIGS[level];
  const pool = cfg.sets.map((setName) => SETS[setName]).join("");
  const chars = cfg.sets.map((setName) => pickChar(SETS[setName]));
  while (chars.length < cfg.length) chars.push(pickChar(pool));
  return shuffle(chars).join("");
}

/* ── entropy estimate: length × log2(character-set size) ── */
function entropyBits(level) {
  const cfg = level === "smart" ? CONFIGS.high : CONFIGS[level];
  const poolSize = cfg.sets.reduce((sum, setName) => sum + SETS[setName].length, 0);
  return Math.round(cfg.length * Math.log2(poolSize));
}

function strengthOf(bits) {
  if (bits < 50) return { labelKey: "strength.weak", color: "var(--dsw-alias-state-error-primary)", pct: 30 };
  if (bits < 80) return { labelKey: "strength.mid", color: "var(--dsw-alias-state-warn-primary)", pct: 65 };
  return { labelKey: "strength.strong", color: "var(--dsw-alias-state-success-primary)", pct: 100 };
}

/* ── dice face (3×3 grid, values 1–6) ── */
const DICE_FACES = {
  1: [[1, 1]],
  2: [[0, 0], [2, 2]],
  3: [[0, 0], [1, 1], [2, 2]],
  4: [[0, 0], [0, 2], [2, 0], [2, 2]],
  5: [[0, 0], [0, 2], [1, 1], [2, 0], [2, 2]],
  6: [[0, 0], [0, 2], [1, 0], [1, 2], [2, 0], [2, 2]],
};
const DICE_GRID = [6.5, 12, 17.5];

function DiceFace({ face, className }) {
  return React.createElement(
    "svg",
    { viewBox: "0 0 24 24", className, "aria-hidden": true },
    React.createElement("rect", { x: 1.2, y: 1.2, width: 21.6, height: 21.6, rx: 5.4, className: "pgw-diceFace" }),
    DICE_FACES[face].map(([row, col], index) =>
      React.createElement("circle", { key: index, cx: DICE_GRID[col], cy: DICE_GRID[row], r: 2.3, className: "pgw-diceDot" }),
    ),
  );
}

