/* ── modal body ── */
function PasswordGeneratorModal({ t, generateMeaningful, onClose, showToast }) {
  const [level, setLevel] = React.useState("mid");
  const [password, setPassword] = React.useState(null); // { text, note } | null
  const [generating, setGenerating] = React.useState(false);
  const [rolling, setRolling] = React.useState(false);
  const [diceFace, setDiceFace] = React.useState(5);
  const [copied, setCopied] = React.useState(false);
  const runSeq = React.useRef(0);
  const rollTimer = React.useRef(null);

  // Unmount (modal close) must stop the dice ticker no matter what is in flight.
  React.useEffect(
    () => () => {
      if (rollTimer.current !== null) clearInterval(rollTimer.current);
    },
    [],
  );

  const clearPassword = React.useCallback(() => {
    runSeq.current += 1; // invalidate any in-flight smart generation
    if (rollTimer.current !== null) {
      clearInterval(rollTimer.current);
      rollTimer.current = null;
    }
    setPassword(null);
    setCopied(false);
    setRolling(false);
    setGenerating(false);
  }, []);

  const switchLevel = React.useCallback(
    (next) => {
      if (next === level) return;
      setLevel(next);
      clearPassword();
    },
    [level, clearPassword],
  );

  const copyPassword = React.useCallback(async () => {
    if (password === null) return;
    const ok = await writeClipboard(password.text);
    if (ok) {
      setCopied(true);
      showToast(t("toast.copied"));
    } else {
      showToast(t("toast.copyFailed"));
    }
  }, [password, showToast, t]);

  const generateNew = React.useCallback(async () => {
    if (generating) return;
    if (level !== "smart") {
      setPassword({ text: generate(level), note: null });
      setCopied(false);
      return;
    }
    const seq = runSeq.current + 1;
    runSeq.current = seq;
    setGenerating(true);
    setRolling(true);
    setPassword(null);
    setCopied(false);
    const timer = setInterval(() => setDiceFace(1 + secureRandomInt(6)), 200);
    rollTimer.current = timer;
    const minDelayMs = 900 + secureRandomInt(500);
    const started = Date.now();
    let answer = null;
    let errorMsg = null;
    try {
      answer = await generateMeaningful({ length: 16 });
    } catch (error) {
      errorMsg = error instanceof Error ? error.message : String(error);
    }
    const elapsed = Date.now() - started;
    if (elapsed < minDelayMs) await new Promise((resolve) => setTimeout(resolve, minDelayMs - elapsed));
    if (rollTimer.current === timer) rollTimer.current = null;
    clearInterval(timer);
    setDiceFace(1 + secureRandomInt(6));
    if (runSeq.current !== seq) return; // a switch/close happened meanwhile — drop the result
    setRolling(false);
    setGenerating(false);
    if (answer !== null && typeof answer.password === "string" && answer.password.length > 0) {
      setPassword({ text: answer.password, note: answer.note ?? "" });
    } else {
      showToast(errorMsg ? `${t("gen.error")} · ${errorMsg}` : t("gen.error"));
      if (errorMsg) console.error("[password-generator] generateMeaningful failed:", errorMsg);
    }
  }, [generating, level, generateMeaningful, showToast, t]);

  const strength = password !== null ? strengthOf(entropyBits(level)) : null;
  const isSmart = level === "smart";

  return React.createElement(
    Modal,
    {
      open: true,
      onClose,
      title: t("modal.title"),
      closeLabel: t("modal.close"),
      className: "pgw-dialog",
      footer: React.createElement(
        Button,
        {
          variant: "primary",
          className: "pgw-genBtn",
          disabled: generating,
          onClick: generateNew,
        },
        generating
          ? t("gen.running")
          : isSmart
            ? t("gen.dice")
            : t("gen.run"),
      ),
    },
    React.createElement(
      "div",
      { className: "pgw-body" },
      React.createElement("div", { className: "pgw-seg", role: "group", "aria-label": t("modal.title") },
        ["low", "mid", "high", "smart"].map((key) =>
          React.createElement(
            "button",
            {
              key,
              type: "button",
              className: [
                "pgw-segBtn",
                level === key ? "pgw-on" : "",
                level === key ? `pgw-on${key[0].toUpperCase()}${key.slice(1)}` : "",
                key === "smart" && rolling ? "pgw-rolling" : "",
              ].filter(Boolean).join(" "),
              title: key === "smart" ? t("seg.smart.title") : undefined,
              "data-level": key,
              onClick: () => switchLevel(key),
              disabled: generating,
            },
            key === "smart"
              ? React.createElement(DiceFace, { face: diceFace, className: "pgw-miniDice" })
              : t(`seg.${key}`),
          ),
        ),
      ),
      React.createElement("div", { className: "pgw-pwBox" },
        React.createElement("span", { className: password === null ? "pgw-pwText pgw-placeholder" : "pgw-pwText" },
          password === null ? t("pw.placeholder") : password.text,
        ),
        React.createElement(
          Button,
          {
            variant: "ghost",
            size: "sm",
            disabled: password === null || generating,
            onClick: copyPassword,
            className: copied ? "pgw-copied" : undefined,
          },
          copied ? t("pw.copied") : t("pw.copy"),
        ),
      ),
      isSmart &&
        React.createElement("div", { className: "pgw-source" },
          React.createElement(DiceFace, { face: 5, className: "pgw-sourceDice" }),
          React.createElement("span", { className: "pgw-sourceText" }, password !== null && password.note ? password.note : t("source.label")),
        ),
      React.createElement("div", { className: "pgw-strength" },
        React.createElement("div", { className: "pgw-strengthBar" },
          React.createElement("div", {
            className: "pgw-strengthFill",
            style: strength === null ? undefined : { width: `${strength.pct}%`, background: strength.color },
          }),
        ),
        React.createElement("span", { className: "pgw-strengthLabel" },
          strength === null ? "—" : `${t(strength.labelKey)} · ${entropyBits(level)} bit`,
        ),
      ),
      React.createElement("div", { className: "pgw-privacy" },
        React.createElement("span", { className: "pgw-shield" }, "🛡"),
        React.createElement("span", null, t("privacy.line")),
      ),
    ),
  );
}

/* ── sidebar footer action entry: trigger + modal + toast ── */
function PasswordGeneratorEntry(props) {
  const { wide, t, generateMeaningful } = props;
  const [open, setOpen] = React.useState(false);
  const [toast, setToast] = React.useState(null); // { text, seq }

  const showToast = React.useCallback((text) => {
    setToast({ text, seq: Date.now() });
  }, []);

  const close = React.useCallback(() => {
    setOpen(false);
    showToast(t("toast.closed"));
  }, [t, showToast]);

  return React.createElement(
    React.Fragment,
    null,
    React.createElement(
      "button",
      {
        type: "button",
        className: wide ? "pgw-trigger" : "pgw-trigger pgw-rail",
        "aria-haspopup": "dialog",
        "aria-expanded": open,
        title: t("entry.title"),
        onClick: () => setOpen(true),
      },
      React.createElement("span", { className: "pgw-key", "aria-hidden": true }, "🔑"),
      wide ? React.createElement("span", { className: "pgw-triggerLabel" }, t("entry.label")) : null,
    ),
    open
      ? React.createElement(PasswordGeneratorModal, { t, generateMeaningful, onClose: close, showToast })
      : null,
    toast !== null
      ? React.createElement(Toast, {
          key: toast.seq,
          text: toast.text,
          onDone: () => setToast(null),
        })
      : null,
  );
}

/* ── plugin entry ── */
const inject = ["slots", "locale", "remote"];

async function apply(ctx) {
  ctx.effect(() => ctx.locale.register(NS, { zh, en }), "ui-password-generator: dictionaries");
  await ctx.remote.$mount(TYPERT_REMOTE);
  // `remote.passwordGenerator` is a cordis service with a dotted name. The
  // traced ctx proxy resolves `ctx.remote.passwordGenerator` through the
  // context, which demands the name be in the `inject` list — but injecting it
  // would deadlock (this plugin mounts it itself in `apply`). `ctx.get(name)`
  // performs the lookup without that gate, so capture the namespace here.
  const passwordGenerator = ctx.get("remote.passwordGenerator");
  ctx.slots.inject("sidebar.footer.action", () =>
    ctx.slots.register(
      {
        name: "sidebar.footer.action",
        id: "password-generator",
        order: 110,
        label: "密码生成器",
        locale: NS,
        inject: () => ({
          generateMeaningful: async (request) => {
            // Belt-and-suspenders client-side bound; the host normally resolves
            // within its own 20s LLM timeout, but this guarantees the UI never
            // hangs on "生成中…" if the carrier stalls.
            const answered = await Promise.race([
              passwordGenerator.generateMeaningful(request),
              new Promise((_, reject) =>
                setTimeout(() => reject(new Error("生成请求超时")), 25000),
              ),
            ]);
            if (!answered.ok) throw new Error(`${answered.error.code}: ${answered.error.message}`);
            return answered.value;
          },
        }),
      },
      PasswordGeneratorEntry,
    ),
  );
}

exports.apply = apply;
exports.inject = inject;
